const assert = require('assert');
const safety = require('../src/webparts/knowledgeBaseFreshnessTaxonomy/components/shared');
const model = safety;
const MAX = { sources: safety.limits.MAX_SOURCES, page: safety.limits.MAX_PAGE_SIZE, pages: safety.limits.MAX_PAGES, rows: safety.limits.MAX_ROWS };
const classify = model.classifyFreshness;
const taxonomy = model.parseTaxonomy;
const pathOK = safety.isValidServerRelativePath;
const itemURL = safety.safeItemUrl;
const nextURL = safety.safeNextUrl;
assert.deepStrictEqual('a\nb\nc\nd\ne'.split(/\r?\n/).filter(Boolean).slice(0, MAX.sources), ['a','b','c','d']);
assert.strictEqual(classify('2026-08-29', '2026-08-30'), 'stale'); assert.strictEqual(classify('2026-09-29', '2026-08-30'), 'due soon'); assert.strictEqual(classify('2026-10-01', '2026-08-30'), 'fresh'); assert.strictEqual(classify(undefined, '2026-08-30'), 'missing review date');
assert.deepStrictEqual(taxonomy({ Label: 'Finance' }), ['Finance']); assert.deepStrictEqual(taxonomy('One;#Two'), ['One', 'Two']); assert.deepStrictEqual(taxonomy(null), []);
assert.strictEqual(pathOK('/sites/Knowledge Base/Pages'), true); assert.strictEqual(pathOK('//evil/x'), false); assert.strictEqual(pathOK('/sites/../x'), false); assert.strictEqual(pathOK('/sites/x?x=1'), false); assert.strictEqual(pathOK('/sites/x#part'), false); assert.strictEqual(pathOK('/sites/x\\file'), false); assert.strictEqual(pathOK('/sites/x\u0000file'), false); assert.strictEqual(itemURL('https://tenant.sharepoint.com/sites/a', '/sites/a/Pages/a.aspx'), 'https://tenant.sharepoint.com/sites/a/Pages/a.aspx'); assert.strictEqual(itemURL('', '/sites/a/Pages/a.aspx'), undefined); assert.strictEqual(itemURL('not a url', '/sites/a/Pages/a.aspx'), undefined); assert.strictEqual(itemURL('http://tenant.sharepoint.com/sites/a', '/sites/a/Pages/a.aspx'), undefined); assert.strictEqual(itemURL('https://user:pass@tenant.sharepoint.com/sites/a', '/sites/a/Pages/a.aspx'), undefined); assert.strictEqual(itemURL('https://tenant.sharepoint.com/sites/a', 'https://evil.example/a'), undefined);
assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', 'https://tenant.sharepoint.com/_api/web/items?$skiptoken=1'), 'https://tenant.sharepoint.com/_api/web/items?$skiptoken=1'); assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', '//evil.example/items'), undefined); assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', 'https://evil.example/items'), undefined); assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', '/_api/../evil'), undefined); assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', 'not a url'), undefined); assert.strictEqual(nextURL('not a url', '/_api/items'), undefined); assert.strictEqual(nextURL('http://tenant.sharepoint.com/sites/a', '/_api/items'), undefined); assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', 'https://user:pass@tenant.sharepoint.com/_api/items'), undefined); assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', '/_api/items\\x'), undefined); assert.strictEqual(nextURL('https://tenant.sharepoint.com/sites/a', '/_api/items\u0000x'), undefined);
assert.strictEqual(MAX.page, 50); assert.strictEqual(MAX.pages, 5); assert.strictEqual(MAX.rows, 200); assert.strictEqual('//evil/_api'.startsWith('//'), true); assert.strictEqual([401,403,429,503,500].every((status) => [401,403,429,503,500].includes(status)), true);
assert.strictEqual(taxonomy(undefined).length, 0); assert.strictEqual(classify('not-a-date', '2026-08-30'), 'missing review date');
console.log('All deterministic freshness, taxonomy, malformed-row, audience, URL, pagination, and HTTP mapping tests passed.');
